# Extra CI lane — a second monitored workflow for the self-heal polygon.
# Same tests as ci.yml, independent failure surface: when the self-heal
# drill breaks THIS workflow, it breaks the command itself (workflow-level
# infra failure), not the test code — the two lanes then produce two
# independent incidents with different cause classes.
# Self-heal keys incidents by FILENAME (wf:ci-extra.yml), one workflow per
# file is a GitHub invariant.
name: CI Extra

on:
  workflow_dispatch:
  push:
    branches:
      - main

# One run per ref at a time; a fresh dispatch supersedes a stale one.
concurrency:
  group: ci-extra-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  test:
    name: test
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Install Dart SDK
